import{_ as i,C as o,o as t,c as l,a4 as a,b as r,w as s,a as d,E as c,a5 as p}from"./chunks/framework.DpieW3qv.js";const y=JSON.parse('{"title":"Action Types","description":"","frontmatter":{"title":"Action Types"},"headers":[],"relativePath":"concepts/action-types.md","filePath":"concepts/action-types.md","lastUpdated":null}'),h={name:"concepts/action-types.md"};function u(m,e,g,b,A,C){const n=o("Mermaid");return t(),l("div",null,[e[1]||(e[1]=a('<h1 id="action-types" tabindex="-1">Action Types <a class="header-anchor" href="#action-types" aria-label="Permalink to &quot;Action Types&quot;">​</a></h1><p>Every zone in a wireframe has an <strong>action</strong> that determines how the system processes it. There are 4 actions.</p><h2 id="available-actions" tabindex="-1">Available Actions <a class="header-anchor" href="#available-actions" aria-label="Permalink to &quot;Available Actions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Description</th><th>Creates New Asset?</th><th>Syncs to SFCC?</th></tr></thead><tbody><tr><td><code>LAUNCH</code></td><td>New content, new asset ID</td><td>Yes</td><td>Yes</td></tr><tr><td><code>UPDATE</code></td><td>Update existing asset content</td><td>No</td><td>Yes</td></tr><tr><td><code>REMOVE</code></td><td>Remove zone from campaign</td><td>No</td><td>Yes (delete)</td></tr><tr><td><code>NO_CHANGE</code></td><td>Keep existing content as-is</td><td>No</td><td>No</td></tr></tbody></table><h2 id="action-flow" tabindex="-1">Action Flow <a class="header-anchor" href="#action-flow" aria-label="Permalink to &quot;Action Flow&quot;">​</a></h2>',5)),(t(),r(p,null,{default:s(()=>[c(n,{id:"mermaid-89",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5BZone%20in%20Wireframe%5D%20--%3E%20B%7BAction%3F%7D%0A%20%20%20%20B%20--%3E%7CLAUNCH%7C%20C%5BGenerate%20New%20Asset%20ID%5D%0A%20%20%20%20B%20--%3E%7CUPDATE%7C%20D%5BReuse%20Existing%20Asset%20ID%5D%0A%20%20%20%20B%20--%3E%7CREMOVE%7C%20E%5BUnregister%20from%20Registry%5D%0A%20%20%20%20B%20--%3E%7CNO_CHANGE%7C%20F%5BReuse%20Asset%20from%20Registry%5D%0A%0A%20%20%20%20C%20--%3E%20G%5BRender%20HTML%5D%0A%20%20%20%20D%20--%3E%20G%0A%0A%20%20%20%20G%20--%3E%20H%5BSave%20to%20Filesystem%5D%0A%20%20%20%20H%20--%3E%20I%7BSync%20Enabled%3F%7D%0A%20%20%20%20I%20--%3E%7CYes%7C%20J%5BPush%20to%20SFCC%5D%0A%20%20%20%20I%20--%3E%7CNo%7C%20K%5BDone%5D%0A%0A%20%20%20%20E%20--%3E%20L%5BDelete%20from%20SFCC%5D%0A%20%20%20%20F%20--%3E%20K%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a(`<h2 id="launch" tabindex="-1">LAUNCH <a class="header-anchor" href="#launch" aria-label="Permalink to &quot;LAUNCH&quot;">​</a></h2><p>Use <code>LAUNCH</code> when introducing completely new content. This:</p><ol><li>Generates a new asset ID based on date/refresh/zone</li><li>Registers the new asset in the Asset Registry</li><li>Creates a new SlotConfiguration in the Campaign</li><li>Renders fresh HTML from the template</li></ol><p><strong>Wireframe Example:</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>| Zone | Action | Headline |</span></span>
<span class="line"><span>|------|--------|----------|</span></span>
<span class="line"><span>| HP_TOP_BANNER | LAUNCH | Spring Sale |</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>Result:</strong></p><ul><li>New asset: <code>loft-2026-02-03-r1-homepage-hp_top_banner</code></li><li>Registry updated with new entry</li></ul><h2 id="update" tabindex="-1">UPDATE <a class="header-anchor" href="#update" aria-label="Permalink to &quot;UPDATE&quot;">​</a></h2><p>Use <code>UPDATE</code> when modifying existing content. This:</p><ol><li>Looks up the current asset ID from the Asset Registry</li><li>Updates the asset&#39;s content (same ID)</li><li>Regenerates HTML</li><li>Pushes updated content to SFCC</li></ol><p><strong>Wireframe Example:</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>| Zone | Action | Headline |</span></span>
<span class="line"><span>|------|--------|----------|</span></span>
<span class="line"><span>| HP_TOP_BANNER | UPDATE | Spring Sale Extended! |</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>Result:</strong></p><ul><li>Reuses existing asset ID from registry</li><li>Content updated, same slot binding</li></ul><h2 id="remove" tabindex="-1">REMOVE <a class="header-anchor" href="#remove" aria-label="Permalink to &quot;REMOVE&quot;">​</a></h2><p>Use <code>REMOVE</code> when content should be deleted. This:</p><ol><li>Unregisters the zone from the Asset Registry</li><li>Deletes the asset from SFCC (if sync enabled)</li><li>Removes the SlotConfiguration binding</li></ol><p><strong>Wireframe Example:</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>| Zone | Action |</span></span>
<span class="line"><span>|------|--------|</span></span>
<span class="line"><span>| HP_BOTTOM_BANNER | REMOVE |</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="no-change" tabindex="-1">NO_CHANGE <a class="header-anchor" href="#no-change" aria-label="Permalink to &quot;NO_CHANGE&quot;">​</a></h2><p>Use <code>NO_CHANGE</code> when content is the same as the previous refresh. This:</p><ol><li>Copies the asset ID from the Asset Registry</li><li>Does NOT regenerate HTML</li><li>Does NOT sync to SFCC</li></ol><p>This is the most common action in wireframes. It keeps existing content in place without any processing or SFCC calls.</p><div class="tip custom-block"><p class="custom-block-title">Asset Registry</p><p>The <code>NO_CHANGE</code> action relies on the Asset Registry to know what&#39;s currently live. Run <code>make registry</code> to see the current state.</p></div><h2 id="force-rebuild" tabindex="-1">Force Rebuild <a class="header-anchor" href="#force-rebuild" aria-label="Permalink to &quot;Force Rebuild&quot;">​</a></h2><p>When you need to regenerate HTML after a template change or fix, use <code>FORCE=1</code> at the CLI level -- not a wireframe action:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> FORCE=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # Regenerate all HTML, bypass build guard</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> FORCE=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # Re-push to SFCC even if already synced</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>This bypasses build guards and forces regeneration of all assets, including DEVELOPER-mode HTML that is normally preserved.</p><h2 id="action-normalization" tabindex="-1">Action Normalization <a class="header-anchor" href="#action-normalization" aria-label="Permalink to &quot;Action Normalization&quot;">​</a></h2><p>Actions are normalized at parse time to canonical values. Both Converted and Changeouts Excel formats produce identical canonical actions:</p><table tabindex="0"><thead><tr><th>Input</th><th>Normalized To</th></tr></thead><tbody><tr><td><code>LAUNCH</code>, <code>NEW</code>, <code>CREATE</code>, <code>ADD</code></td><td><code>LAUNCH</code></td></tr><tr><td><code>UPDATE</code>, <code>EDIT</code>, <code>MODIFY</code>, <code>CHANGE</code></td><td><code>UPDATE</code></td></tr><tr><td><code>REMOVE</code>, <code>DELETE</code>, <code>DROP</code></td><td><code>REMOVE</code></td></tr><tr><td><code>NO_CHANGE</code>, <code>NO CHANGE</code>, <code>NO CHANGE/LINK SAME</code>, <code>REUSE</code></td><td><code>NO_CHANGE</code></td></tr><tr><td><em>(empty cell)</em></td><td><code>NO_CHANGE</code></td></tr></tbody></table><p>Any other value triggers an unknown-action warning and defaults to <code>NO_CHANGE</code>.</p><p><strong>Example walkthrough:</strong></p><table tabindex="0"><thead><tr><th>Excel Cell Value</th><th>After normalization</th><th>What happens</th></tr></thead><tbody><tr><td><code>NO CHANGE/LINK SAME</code></td><td><code>NO_CHANGE</code></td><td>No HTML regen, no sync, no registry change</td></tr><tr><td><code>NEW</code></td><td><code>LAUNCH</code></td><td>New asset ID, render HTML, sync to SFCC</td></tr><tr><td><em>(empty cell)</em></td><td><code>NO_CHANGE</code></td><td>Zone unchanged</td></tr></tbody></table><h2 id="dominant-action-rule" tabindex="-1">Dominant Action Rule <a class="header-anchor" href="#dominant-action-rule" aria-label="Permalink to &quot;Dominant Action Rule&quot;">​</a></h2><p>When a zone has multiple items with different actions, the highest-priority action wins:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LAUNCH &gt; UPDATE &gt; REMOVE &gt; NO_CHANGE</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><strong>Use LAUNCH sparingly</strong> -- Only for genuinely new content</li><li><strong>Prefer UPDATE</strong> -- Keeps asset history and slot bindings intact</li><li><strong>Use NO_CHANGE liberally</strong> -- Reduces processing time and OCAPI calls</li><li><strong>Use REMOVE to clean up</strong> -- Properly unregisters and deletes from SFCC</li></ol><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/ocapi-docs.github.io/config/registry.html">Asset Registry</a> -- How the registry tracks current assets</li><li><a href="/ocapi-docs.github.io/reference/commands.html">Commands</a> -- All workflow commands</li></ul>`,41))])}const N=i(h,[["render",u]]);export{y as __pageData,N as default};
